%%\ Gaussian Noise Denoising: Traditional Filters vs. Pre-trained AI (DnCNN)
close all; clear; clc;
rng(42); % Reproducible Gaussian noise realization

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

%%\ --- 1. Setup: Load an image and add Gaussian noise ---
originalImage = im2double(imread('cameraman.tif'));
noiseSigma    = 0.04;
noisyImage    = imnoise(originalImage, 'gaussian', 0, noiseSigma^2);

%%\ --- 2. Traditional Filters (Adaptive Wiener + Mean, Median, Gaussian) ---
% Adaptive Wiener filter adjusts smoothing based on local neighborhood variance
traditionalFiltered = wiener2(noisyImage, [5 5], noiseSigma^2);

% Additional classic spatial filters for learning-outcome comparison
meanFiltered     = imfilter(noisyImage, fspecial('average', 3), 'replicate');
medianFiltered   = medfilt2(noisyImage, [3 3]);
gaussianFiltered = imgaussfilt(noisyImage, 1.0);

%%\ --- 3. AI Filter (Pre-trained DnCNN) ---
net        = denoisingNetwork('DnCNN');
aiFiltered = denoiseImage(noisyImage, net);

% Figure 1: Main 4-panel comparison (2x2 layout prevents title overlap)
f1 = figure('Name', 'Gaussian Noise Denoising Comparison'); %[output:720169ff]
tiledlayout(2, 2, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:720169ff]

nexttile; imshow(originalImage);       title('1. Original Image'); %[output:720169ff]
nexttile; imshow(noisyImage);          title('2. Noisy Image (\sigma = 0.04)'); %[output:720169ff]
nexttile; imshow(traditionalFiltered); title('3. Traditional (Wiener 5x5)'); %[output:720169ff]
nexttile; imshow(aiFiltered);          title('4. AI (DnCNN) Filter'); %[output:720169ff]

saveas(f1, fullfile('screenshots', '01_wiener_vs_dncnn.png')); %[output:720169ff]

% Figure 2: Comparison across classic traditional spatial filters
f2 = figure('Name', 'Traditional Spatial Filters Comparison'); %[output:901f6b32]
tiledlayout(2, 2, 'TileSpacing', 'compact', 'Padding', 'compact'); %[output:901f6b32]

nexttile; imshow(meanFiltered);        title('Mean Filter (3x3)'); %[output:901f6b32]
nexttile; imshow(medianFiltered);      title('Median Filter (3x3)'); %[output:901f6b32]
nexttile; imshow(gaussianFiltered);    title('Gaussian Blur (\sigma = 1.0)'); %[output:901f6b32]
nexttile; imshow(traditionalFiltered); title('Adaptive Wiener (5x5)'); %[output:901f6b32]

saveas(f2, fullfile('screenshots', '02_traditional_filters.png')); %[output:901f6b32]

%%\ --- 4. Quantitative Evaluation (MSE, PSNR, and SSIM) ---
mseNoisy        = immse(noisyImage, originalImage);
psnrNoisy       = psnr(noisyImage, originalImage);
ssimNoisy       = ssim(noisyImage, originalImage);

mseTraditional  = immse(traditionalFiltered, originalImage);
psnrTraditional = psnr(traditionalFiltered, originalImage);
ssimTraditional = ssim(traditionalFiltered, originalImage);

mseAI           = immse(aiFiltered, originalImage);
psnrAI          = psnr(aiFiltered, originalImage);
ssimAI          = ssim(aiFiltered, originalImage);

fprintf('\n--- Image Quality Metrics Comparison ---\n'); %[output:83618f97]
fprintf('Method               | MSE      | PSNR (dB) | SSIM\n'); %[output:53075905]
fprintf('---------------------|----------|-----------|----------\n'); %[output:8938d05d]
fprintf('Noisy Image          | %8.6f | %9.4f | %8.4f\n', mseNoisy, psnrNoisy, ssimNoisy); %[output:5438066e]
fprintf('Traditional (Wiener) | %8.6f | %9.4f | %8.4f\n', mseTraditional, psnrTraditional, ssimTraditional); %[output:47b0855f]
fprintf('AI (DnCNN)           | %8.6f | %9.4f | %8.4f\n', mseAI, psnrAI, ssimAI); %[output:32ae8665]

% Print complete Markdown table rows (all filters) for README.md
fprintf('\n--- Copy into README.md ---\n'); %[output:0b6d7aa4]
labels = {'Noisy Image (\sigma = 0.04)', 'Mean Filter (3x3)', 'Median Filter (3x3)', ...
    'Gaussian Blur (\sigma = 1.0)', 'Adaptive Wiener (5x5)', 'AI Filter (DnCNN)'};
images = {noisyImage, meanFiltered, medianFiltered, gaussianFiltered, traditionalFiltered, aiFiltered};

for k = 1:numel(labels) %[output:group:0d06ef18]
    fprintf('| %s | %.6f | %.2f dB | %.4f |\n', ... %[output:18e66309]
        labels{k}, immse(images{k}, originalImage), psnr(images{k}, originalImage), ssim(images{k}, originalImage)); %[output:18e66309]
end %[output:group:0d06ef18]

%%\ --- 5. Visual Observation ---
% DnCNN removes additive white Gaussian noise across smooth sky areas while
% keeping sharp edges (coat, tripod, buildings) crisp. Adaptive Wiener
% outperforms fixed Mean, Median, and Gaussian filters by scaling down
% smoothing near high-variance edges, though slight residual grain remains.

